// سكريبت لملء دليل الكليات (Firestore collection: collegesGuide) بدفعة أولى
// من الكليات الأكثر طلبًا، بكل الحقول المطلوبة (نبذة، أقسام، رواتب، تأثير AI...).
//
// طريقة التشغيل (مرة واحدة على جهازك، مش على Vercel):
//   1) npm install firebase-admin
//   2) نزّل ملف الـService Account JSON بتاعك من Firebase Console
//      (Project Settings -> Service Accounts -> Generate New Private Key)
//      وسمّيه serviceAccountKey.json وحطه جنب السكريبت ده.
//   3) node seed-colleges.js
//
// السكريبت آمن للتكرار: بيدور على كلية بنفس الاسم قبل ما يضيفها، فلو شغّلته
// أكتر من مرة مش هيعمل تكرار (duplicate) في القاعدة.

const admin = require("firebase-admin");
const serviceAccount = require("./serviceAccountKey.json");

admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  projectId: serviceAccount.project_id,
});
const db = admin.firestore();

