async function seed() {
  const collectionRef = db.collection("collegesGuide");
  let added = 0, skipped = 0;
  for (const college of COLLEGES) {
    const existing = await collectionRef.where("name", "==", college.name).limit(1).get();
    if (!existing.empty) {
      console.log(`⏭️  متخطّي (موجود بالفعل): ${college.name}`);
      skipped++;
      continue;
    }
    await collectionRef.add({ ...college, updatedAt: Date.now() });
    console.log(`✅ اتضافت: ${college.name}`);
    added++;
  }
  console.log(`\nخلاص: ${added} كلية اتضافت، ${skipped} كانت موجودة من قبل.`);
  process.exit(0);
}

seed().catch(err => {
  console.error("حصل خطأ أثناء الإضافة:", err);
  process.exit(1);
});
